import os

# First, locate the actual input file - it might be in a specific task directory
user_path = "/home/USER/runs/paper/qwen-h0-card/frozen/held-out-reference-3/play/users/u013"

def search_for_input_files(d, max_depth=2):
    """Recursively find .txt files"""
    results = []
    for root, dirs, files in os.walk(d):
        # Limit depth
        depth = root.replace(d, '').count(os.sep)
        if depth >= max_depth:
            continue
        for f in files:
            if f.endswith('.txt'):
                full = os.path.join(root, f)
                try:
                    size = os.path.getsize(full)
                    if 100 < size < 50000:  # Reasonable file size
                        results.append((full, size))
                except:
                    pass
    return sorted(results, key=lambda x: -x[1])

input_files = search_for_input_files(user_path)
